<script setup lang="ts">
import FilePicker from '@/components/FilePicker.vue'
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {ElMessage} from 'element-plus'
import {get,post,http,errorMessage} from '@/api/client'
const title=ref('验证集测试'),file=ref<File>(),models=ref<any[]>([]),bases=ref<any[]>([]),modelId=ref(''),knowledgeBaseIds=ref<string[]>([]),jobs=ref<any[]>([]),selected=ref<any>(),busy=ref(false);let timer:ReturnType<typeof setInterval>
const labels:Record<string,string>={QUEUED:'排队中',RUNNING:'执行中',COMPLETED:'已完成',FAILED:'失败',SUCCESS:'成功',PENDING:'待执行',CANCELLED:'已停止',CANCELLING:'正在停止',INTERRUPTED:'已中断',SKIPPED:'已跳过'}
async function load(){jobs.value=await get<any[]>('/evaluations');if(selected.value)selected.value=await get('/evaluations/'+selected.value.id)}
async function select(id:string){try{selected.value=await get('/evaluations/'+id)}catch(e){ElMessage.error(errorMessage(e))}}
function choose(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;if(!/\.xlsx$/i.test(f.name)||f.size>1_000_000){ElMessage.error('请选择不超过 1MB 的 .xlsx 文件');(e.target as HTMLInputElement).value='';file.value=undefined;return}file.value=f;title.value=f.name.replace(/\.xlsx$/i,'').slice(0,120)}
async function start(){if(!file.value||busy.value)return;busy.value=true;try{const data=await new Promise<string>((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(Error('文件读取失败'));r.readAsDataURL(file.value!)});const task=await post<any>('/evaluations',{title:title.value,format:'xlsx',data,modelId:modelId.value||undefined,knowledgeBaseIds:knowledgeBaseIds.value});await load();await select(task.id)}catch(e){ElMessage.error(errorMessage(e))}finally{busy.value=false}}
async function download(template=false){try{const r=await http.get(template?'/evaluations/template':'/evaluations/'+selected.value.id+'/export',{params:template?undefined:{format:'xlsx'},responseType:'blob'}),url=URL.createObjectURL(r.data),a=document.createElement('a');a.href=url;a.download=template?'validation-template.xlsx':'validation-results.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){ElMessage.error(errorMessage(e))}}
async function cancel(){try{await post('/evaluations/'+selected.value.id+'/cancel');await load()}catch(e){ElMessage.error(errorMessage(e))}}
onMounted(async()=>{try{await Promise.all([load(),get<any[]>('/models/available').then(v=>models.value=v),get<any[]>('/evaluations/knowledge-options').then(v=>bases.value=v)]);if(jobs.value[0])await select(jobs.value[0].id)}catch(e){ElMessage.error(errorMessage(e))}timer=setInterval(()=>{if(!document.hidden&&selected.value&&['RUNNING','QUEUED','CANCELLING'].includes(selected.value.status))void load().catch(()=>{})},3000)})
onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><div class="validation-page"><header><h1>验证集批量测试</h1><p>上传问题与预期答案，逐题获取真实回复并导出评审材料。</p></header><div class="validation-grid"><section><h2>上传验证集</h2><p>仅支持 Excel（.xlsx），一个工作表，两列：问题、预期答案。最多 500 题、1MB，每题独立回答。参考答案只用于核对，不发送给模型。</p><el-button @click="download(true)">下载 Excel 模板</el-button><div style="margin:20px 0"><FilePicker accept=".xlsx" :file="file" :disabled="busy" label="选择验证集" hint="Excel · 最大 1 MB" @change="choose"/></div><label>任务名称<el-input v-model="title" maxlength="120"/></label><label>模型（可选）<el-select v-model="modelId" clearable placeholder="使用平台默认模型"><el-option v-for="m in models" :key="m.id" :label="m.name" :value="m.id"/></el-select></label><label>知识库（可选）<el-select v-model="knowledgeBaseIds" multiple clearable collapse-tags placeholder="使用当前已挂载的公共知识库"><el-option v-for="b in bases" :key="b.id" :label="b.name" :value="b.id"/></el-select></label><p>选择后只检索所选库，不改变全站挂载设置；不选择则沿用当前挂载范围。</p><label>回答模式<el-input model-value="精简模式（固定）" disabled/></label><p>固定纯文字，保留必要事实和步骤。绕过回答缓存、不读写个人记忆，不提供卡片、模式或智能体切换。</p><el-button type="primary" :loading="busy" :disabled="!file||!title.trim()" @click="start">开始测试</el-button></section><section><h2>执行与结果</h2><button class="job" v-for="j in jobs" :key="j.id" @click="select(j.id)">{{j.title}} · {{labels[j.status]||j.status}} {{j.completed}}/{{j.total}}</button><template v-if="selected"><h3>{{selected.title}}</h3><el-progress :percentage="Math.round(selected.completed/selected.total*100)"/><p>成功 {{selected.succeeded}} · 失败 {{selected.failed}} · {{labels[selected.status]||selected.status}}</p><el-button @click="download()">下载 Excel 结果</el-button><el-button v-if="['RUNNING','QUEUED','CANCELLING'].includes(selected.status)" @click="cancel">停止</el-button><p v-if="selected.error">{{selected.error}}</p><article v-for="t in selected.turns" :key="t.id"><h4>{{t.question}}</h4><p>预期答案：{{t.expectedAnswer||'未提供'}}</p><pre>{{t.reply||t.error||'等待回复'}}</pre><small>{{labels[t.status]||t.status}} · {{t.latencyMs}} 毫秒</small></article></template><p v-else>上传验证集开始测试。结果文件前三列为问题、预期答案、智能体实际回复，附带耗时与异常状态。</p></section></div></div></template>
<style scoped>.validation-page{max-width:1400px;margin:auto;padding:24px;color:var(--nx-text)}h1{font-size:26px}h2{font-size:18px}.validation-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.2fr);gap:20px}.validation-grid section{padding:24px;border:1px solid var(--nx-border);border-radius:16px;background:var(--nx-surface);min-width:0}p,small{color:var(--nx-text-3);font-size:13px;line-height:1.8}label{display:grid;gap:8px;margin:20px 0;font-size:14px}.el-select{width:100%}input[type=file]{max-width:100%}.job{display:block;width:100%;text-align:left;padding:12px;margin:8px 0;border:1px solid var(--nx-border);border-radius:8px;background:var(--nx-surface-2);color:var(--nx-text);cursor:pointer}article{border-top:1px solid var(--nx-border);margin-top:20px;padding-top:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;line-height:1.7}@media(max-width:900px){.validation-grid{grid-template-columns:1fr}.validation-page{padding:16px}}</style>
